 * @var array<int, array{methods: string, path: string, name: string, handler: string, middleware: string}> $routes
 * @var array<int, string> $middleware_chain Class short names, in execution order, as run by the Kernel.
 * @var array<int, string> $permissions Permission codes granted to the signed-in role (Phase 8).
 * @var string $scope_label Human label for the user's data scope.
 */

$middlewareChain = $middleware_chain;
?>
<section class="hero">
    <p class="eyebrow">Phase 8 · Role-based access</p>
    <h1>
        <?php if ($user !== null): ?>
            Welcome back, <?= $e($user['first_name']) ?>.
        <?php else: ?>
            Requests now travel through a real pipeline.
        <?php endif; ?>
    </h1>
    <p class="lede">
        This page was matched by the router, authorised by the middleware chain, assembled by
        <code>App\Controllers\HomeController</code> and rendered by <code>App\Core\View</code>.
        Nothing on this screen is served by the front controller directly.
    </p>
    <ul class="badges">
        <li>PHP <?= $e($php_version) ?></li>
        <li><?= $e($environment) ?> environment</li>
        <li><?= $e($timezone) ?></li>
        <?php if ($boot_ms !== null): ?>
            <li><?= $e($boot_ms) ?> ms boot</li>
        <?php endif; ?>
        <li><?= $e($base_url) ?></li>
    </ul>
</section>

<div class="grid">
    <section class="card">
        <header class="card-head">
            <h2>This request</h2>
            <span class="tag"><?= $e($server_software) ?></span>
        </header>
        <dl class="facts">
            <?php if ($user !== null): ?>
                <div>
                    <dt>Signed in as</dt>
                    <dd>
                        <?= $e($user['first_name'] . ' ' . $user['last_name']) ?>
                        · <code><?= $e($user['role_name']) ?></code>
                    </dd>
                </div>
                <div>
                    <dt>Email</dt>
                    <dd><?= $e($user['email']) ?></dd>
                </div>
            <?php endif; ?>
            <div>
                <dt>Matched route</dt>
                <dd><code><?= $e($route_name) ?></code></dd>
            </div>
            <div>
                <dt>Handler</dt>
                <dd><code><?= $e($route_summary) ?></code></dd>
            </div>
            <div>
                <dt>Middleware</dt>
                <dd><code><?= $e(implode(' → ', $middlewareChain)) ?></code></dd>
            </div>
            <div>
                <dt>Session</dt>
                <dd><code><?= $e($session_id !== '' ? $session_id . '…' : 'not started') ?></code></dd>
            </div>
            <div>
                <dt>CSRF token</dt>
                <dd><?= $csrf_present ? 'issued and stored in the session' : 'unavailable' ?></dd>
            </div>
            <div>
                <dt>Database target</dt>
                <dd><code><?= $e($database['driver']) ?></code> · <?= $e($database['name']) ?> @ <?= $e($database['host']) ?></dd>
            </div>
        </dl>
        <?php if ($session_expired !== null): ?>
            <p class="alert alert-warn">
                The previous session ended (<?= $e($session_expired) ?>). A new session was started for this request.
            </p>
        <?php endif; ?>
    </section>

    <section class="card">
        <header class="card-head">
            <h2>CSRF probe</h2>
            <span class="tag">POST</span>
        </header>
        <p class="muted">
            This form posts to <code><?= $e($route('pipeline.echo')) ?></code>. The <code>csrf</code>
            middleware verifies the hidden token before the controller runs; a request without it is answered
            with <code>419</code>.
        </p>
        <form class="probe" method="post" action="<?= $e($route('pipeline.echo')) ?>">
            <?= $csrf_field() ?>
            <label for="message">Probe message</label>
            <input id="message" name="message" type="text" value="Pipeline online" maxlength="120" required>
            <button type="submit">Send through the pipeline</button>
        </form>
        <p class="hint">
            A successful post returns JSON: <code>{"ok":true,"csrf":"verified",…}</code>
        </p>
    </section>

    <section class="card">
        <header class="card-head">
            <h2>Your access</h2>
            <span class="tag"><?= $e(count($permissions)) ?> permissions</span>
        </header>
        <?php if ($user !== null): ?>
            <dl class="facts">
                <div>
                    <dt>Role</dt>
                    <dd><code><?= $e($user['role_code']) ?></code> · <?= $e($user['role_name']) ?></dd>
                </div>
                <div>
                    <dt>Data scope</dt>
                    <dd><?= $e($scope_label) ?></dd>
                </div>
                <div>
                    <dt>Department</dt>
                    <dd><?= $e($user['department_name'] ?? 'Institution-wide') ?></dd>
                </div>
            </dl>
            <p class="hint">
                Granted by <code>config/permissions.php</code> and stored in <code>role_permissions</code>.
                A permission that is not in the catalogue is denied to every role, including the administrator.
            </p>
            <ul class="badges">
                <?php foreach ($permissions as $permission): ?>
                    <li><code><?= $e($permission) ?></code></li>
                <?php endforeach; ?>
            </ul>
        <?php else: ?>
            <p class="muted">Sign in to see the permissions of your role.</p>
        <?php endif; ?>
    </section>
</div>

<section class="card">
    <header class="card-head">
        <h2>Route table</h2>
        <span class="tag"><?= $e(count($routes)) ?> routes</span>
    </header>
    <div class="table-wrap">
        <table>
            <thead>
            <tr>
                <th scope="col">Method</th>
                <th scope="col">Path</th>
                <th scope="col">Name</th>
                <th scope="col">Handler</th>
                <th scope="col">Middleware</th>
            </tr>
            </thead>
            <tbody>
            <?php foreach ($routes as $item): ?>
                <tr>
                    <td><span class="method"><?= $e($item['methods']) ?></span></td>
                    <td><code><?= $e($item['path']) ?></code></td>
                    <td><code><?= $e($item['name']) ?></code></td>
                    <td class="muted"><?= $e($item['handler']) ?></td>
                    <td class="muted"><?= $e($item['middleware']) ?></td>
                </tr>
            <?php endforeach; ?>
            </tbody>
        </table>
    </div>
</section>

<section class="card">
    <header class="card-head">
        <h2>What this phase installed</h2>
        <span class="tag">Phase 8</span>
    </header>
    <ul class="checks">
        <li><strong>Catalogue</strong> — every capability is a row in <code>permissions</code>, written from <code>config/permissions.php</code>.</li>
        <li><strong>Matrix</strong> — four roles, explicit grants only: no wildcard, no inheritance, no administrator bypass.</li>
        <li><strong>Middleware</strong> — <code>permission:users.view</code> and <code>role:dean</code> rules run after <code>auth</code> and fail closed.</li>
        <li><strong>Scope</strong> — repositories take an <code>App\Services\Scope</code>, so dean and faculty queries are filtered in SQL.</li>
        <li><strong>Audit</strong> — every refusal is written as <code>authz.denied</code> with the route and required rules.</li>
    </ul>
    <p class="hint">
        Try <a href="<?= $e($route('admin.users.index')) ?>">/admin/users</a> with different roles: the same page shows
        everybody for the administrator, one department for a dean or secretary, and only yourself for faculty.
    </p>
</section>
